"""specs_s200047.py - Sonnet-w2 family Y2 (generated by mkfamY2.py): 0x469870 and the engine table slot 0x114 stub (4 stack args, returns a random value; both calls recorded with the SEH chain and
the object's vtable word); fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    o = rnd(c, 0x100)
    hook_rec(c, 0x469870, 0, ret=r.getrandbits(32), this=True, side=_side(c, o))
    eng = rnd(c, 0x1b00)
    c.emu.w32(0x70039c, eng)
    t = obj(c, 0x40, {0x114: pystub(c, 4, ret=lambda emu, k: r.getrandbits(32), this=True, side=_side(c, o))}, nslots=0x50)
    c.emu.w32(eng + 0x9b, t)
    return [o]


S(0x4ca8f0, 'GUESS famY2 0x4ca8f0', 'thiscall', None, ret='eax', gen=_gen, note='batch200047')
S(0x5b7f00, 'GUESS famY2 0x5b7f00', 'thiscall', None, ret='eax', gen=_gen, note='batch200047')
